'use strict';
// Agriculture uses a separate deterministic stream; rendering never rolls outcomes.
const FARM_COST=800,FARM_WIN_RATE=.52;
let farmReviewVisible=false,farmPointer=null,farmPlacementKey="",farmPlacements=new Map();
function agricultureState(){return S.agriculture??={version:1,planted:0,completed:0,income:0,profit:0,history:[],curve:[],pending:null};}
function farmEligible(c){return !!c&&!c.removed&&c.kind!=='bridgehead'&&c.shape===0;}
function farmRoundPayout(seed,cityId,round){return marketRng(marketHash('farm-v1:'+seed+':'+cityId+':'+round))()<FARM_WIN_RATE?1000:650;}
function farmDueAt(start){return Math.floor(start)+9.5;}
function farmDate(day){return '第'+(Math.floor(day)+1)+'天 '+String(Math.floor((day%1)*24+1e-6)).padStart(2,'0')+':00';}
function farmMoney(n){return (n>0?'+':n<0?'−':'')+'¥'+Math.abs(n).toLocaleString('zh-CN',{maximumFractionDigits:2});}
function plantFarm(id){let c=S.cities[id],a=agricultureState();if(!farmEligible(c))return toast('只有居住城市可以种植农田');if(c.dormant)return toast('请先接通这座居住城市');if(S.lives<=0)return toast('本局已结束');if(a.pending)return toast('请先查看本批收获结果');if(c.farm?.crop)return toast('这块农田正在种植');if(S.points<FARM_COST)return toast('本轮种植需要 ¥800');
 let f=c.farm??={round:0,completed:0,income:0,profit:0,history:[],crop:null};f.round++;let start=S.day;
 spend(FARM_COST,'agricultureInvestment',c.name+'农田第'+f.round+'轮种植');f.crop={round:f.round,start,due:farmDueAt(start),payout:farmRoundPayout(S.seed,c.id,f.round)};a.planted++;if(!a.curve.length)a.curve.push({day:start,profit:a.profit});save();updateUI();showFarm(id);
}
function settleFarms(wasRunning=!S.paused){let a=agricultureState(),due=S.cities.filter(c=>c.farm?.crop&&c.farm.crop.due<=S.day+1e-9).sort((x,y)=>x.farm.crop.due-y.farm.crop.due||x.id-y.id);if(!due.length)return false;
 let rows=[];for(let c of due){let f=c.farm,crop=f.crop;f.crop=null;let row={id:c.id+':'+crop.round,cityId:c.id,name:c.name,round:crop.round,start:crop.start,day:crop.due,cost:FARM_COST,income:crop.payout,profit:crop.payout-FARM_COST};f.completed++;f.income+=row.income;f.profit+=row.profit;f.history.push(row);f.history=f.history.slice(-30);f.lastHarvest=row;rows.push(row);a.completed++;a.income+=row.income;a.profit+=row.profit;a.history.push(row);credit(row.income,'agricultureIncome',c.name+'农田收获 · '+(row.profit>0?'丰收':'歉收'));
 let last=a.curve.at(-1);if(last&&Math.abs(last.day-row.day)<1e-9)last.profit=a.profit;else a.curve.push({day:row.day,profit:a.profit});}
 a.history=a.history.slice(-200);a.curve=a.curve.slice(-400);if(a.pending)a.pending.rows.push(...rows);else a.pending={rows,wasRunning};S.paused=true;save();updateUI();return true;
}
function farmTotals(){let a=agricultureState();return {investment:a.planted*FARM_COST,pending:S.cities.filter(c=>c.farm?.crop).length*FARM_COST,completed:a.completed,income:a.income,profit:a.profit};}
function farmChart(points){if(!points.length)return '<div class="farm-empty">收获第一轮后显示累计盈亏曲线</div>';let lo=Math.min(0,...points.map(p=>p.profit)),hi=Math.max(0,...points.map(p=>p.profit)),pad=Math.max(40,(hi-lo)*.15);lo-=pad;hi+=pad;let start=points[0].day,end=Math.max(start+1,points.at(-1).day),y=n=>115-(n-lo)/(hi-lo)*96,x=d=>40+(d-start)/(end-start)*460,line=points.map(p=>x(p.day).toFixed(1)+','+y(p.profit).toFixed(1)).join(' ');return `<figure class="farm-chart"><figcaption>已收获轮次 · 累计净利润</figcaption><svg viewBox="0 0 520 145" role="img" aria-label="农业累计净利润曲线，最新${farmMoney(points.at(-1).profit)}"><line x1="40" y1="${y(0)}" x2="500" y2="${y(0)}" stroke="#aebbb2" stroke-dasharray="4 4"/><text x="6" y="${y(0)+4}" font-size="10" fill="#748579">0</text><polyline points="${line}" fill="none" stroke="${points.at(-1).profit>=0?'#558877':'#bc725c'}" stroke-width="2.5" stroke-linejoin="round"/><circle cx="${x(points.at(-1).day)}" cy="${y(points.at(-1).profit)}" r="3.5" fill="#527e70"/><text x="40" y="139" font-size="10" fill="#748579">第${Math.floor(start)+1}天</text><text x="500" y="139" text-anchor="end" font-size="10" fill="#748579">第${Math.floor(points.at(-1).day)+1}天</text></svg></figure>`;}
function farmMetrics(t){return `<div class="farm-metrics"><div><small>已实现净利润</small><b class="${t.profit>=0?'positive':'negative'}">${farmMoney(t.profit)}</b></div><div><small>累计收获 / 完成轮数</small><b>¥${t.income.toLocaleString('zh-CN')} / ${t.completed}轮</b></div><div><small>种植中投入</small><b>¥${t.pending.toLocaleString('zh-CN')}</b></div></div>`;}
function farmHistory(rows){return rows.length?`<div class="farm-table-wrap"><table class="farm-table"><thead><tr><th>城市 / 收获</th><th>投入</th><th>到账</th><th>净盈亏</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${escapeHTML(r.name)}</b><small>${farmDate(r.day)} · 第${r.round}轮</small></td><td>¥${r.cost}</td><td>¥${r.income}</td><td class="${r.profit>=0?'positive':'negative'}">${farmMoney(r.profit)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="market-muted">暂无收获记录。</p>';}
function showFarmHarvest(){let a=agricultureState();if(!a.pending)return;let rows=a.pending.rows,total=rows.reduce((t,r)=>t+r.profit,0),income=rows.reduce((t,r)=>t+r.income,0);farmReviewVisible=true;S.paused=true;openModal(`<div class="farm-sheet" data-farm-harvest><div class="modal-head"><div><span class="eyebrow">12:00 / HARVEST REPORT</span><h2>农田收获</h2></div><button class="close" onclick="finishFarmHarvest()" aria-label="确认农田收获">×</button></div><p class="farm-paused">主世界、交通工具与游戏时间已暂停。</p><section class="farm-batch"><small>本批 ${rows.length}块田 · 已到账 ¥${income.toLocaleString('zh-CN')}</small><strong class="${total>=0?'positive':'negative'}">净${total>=0?'赚':'亏'} ¥${Math.abs(total).toLocaleString('zh-CN')}</strong></section>${farmHistory(rows)}${farmMetrics(farmTotals())}${farmChart(a.curve)}<p class="market-muted">净利润只统计已收获轮次，正在种植的800单独列示。收获款已计入现金，若有维护欠款会按原规则优先偿还。不会自动续种。</p><button class="primary farm-continue" onclick="finishFarmHarvest()">${a.pending.wasRunning?'继续经营':'确认收获，保持暂停'}</button></div>`);save();}
function maybeFarmHarvest(){let a=S.agriculture;if(!a?.pending)return;S.paused=true;if(modalOpen||draft||bridgeDraft||pointers.size)return;showFarmHarvest();}
function finishFarmHarvest(){closeModal();}
const closeBeforeFarms=closeModal;
closeModal=function(){let a=S.agriculture,review=farmReviewVisible&&a?.pending,wasRunning=review?.wasRunning;if(review){a.pending=null;farmReviewVisible=false;}closeBeforeFarms();if(review){S.paused=!!wasRunning&&S.lives>0?false:true;save();updateUI();}};
function farmStage(c){let crop=c.farm?.crop;if(!crop)return -1;let day=Math.floor(S.day)-Math.floor(crop.start);return day<3?0:day<6?1:day<9?2:3;}
function farmStageName(c){return ['翻土育种','幼苗生长','作物生长','成熟待收'][farmStage(c)]||'空田 · 可开始新一轮';}
function showFarm(id){let c=S.cities[id];if(!farmEligible(c))return;let f=c.farm,crop=f?.crop,points=f?.history.length?[{day:f.history[0].start,profit:f.profit-f.history.reduce((n,r)=>n+r.profit,0)},...f.history.map((r,i,rs)=>({day:r.day,profit:f.profit-rs.slice(i+1).reduce((n,x)=>n+x.profit,0)}))]:[];
 openModal(`<div class="farm-sheet"><div class="modal-head"><div><span class="eyebrow">RESIDENTIAL AGRICULTURE</span><h2>${escapeHTML(c.name)} · 农田</h2></div><button class="close" onclick="closeModal()" aria-label="关闭农田详情">×</button></div><p>每座中级及以上居住城市一块农田，每轮投入800。丰收52%：收回1000，净赚200；歉收48%：收回650，净亏150。</p><section class="farm-status"><b>${farmStageName(c)}</b>${crop?`<p>本轮投入 ¥800 · ${farmDate(crop.due)}收获<br>播种当天为第1天，第10天中午12:00自动到账。</p><progress max="1" value="${Math.max(0,Math.min(1,(S.day-crop.start)/(crop.due-crop.start)))}"></progress>`:`<p>播种当天为第1天，第10天中午12:00自动到账；收获后自行决定是否续种。</p><button class="primary" onclick="plantFarm(${id})" ${c.size<1||c.dormant||S.points<FARM_COST||S.lives<=0||agricultureState().pending?'disabled':''}>${c.size<1?'需要中级居住城市':c.dormant?'先接通城市':S.points<FARM_COST?'种植资金不足':'投入 ¥800，开始种植'}</button>`}</section>${farmMetrics({profit:f?.profit||0,income:f?.income||0,completed:f?.completed||0,pending:crop?FARM_COST:0})}${farmChart(points)}<h3>最近收获</h3>${farmHistory((f?.history||[]).slice(-10).reverse())}<div class="ux-actions"><button onclick="showAgriculture()">全部农田与盈亏</button><button onclick="closeModal()">回到地图</button></div></div>`);
}
function agricultureSummary(){let t=farmTotals();return `<section class="infra-card"><h3>农业经营</h3><p>累计投入 ¥${t.investment.toLocaleString('zh-CN')} · 收获收入 ¥${t.income.toLocaleString('zh-CN')}<br>已收获净利润 ${farmMoney(t.profit)} · 种植中投入 ¥${t.pending.toLocaleString('zh-CN')}</p><button onclick="showAgriculture()">农田与盈亏记录</button></section>`;}
function showAgriculture(){let a=agricultureState();openModal(`<div class="farm-sheet"><div class="modal-head"><div><span class="eyebrow">AGRICULTURE / 10 DAYS</span><h2>农田与盈亏</h2></div><button class="close" onclick="closeModal()" aria-label="关闭农业经营">×</button></div>${farmMetrics(farmTotals())}${farmChart(a.curve)}<p class="market-muted">每轮800，丰收52%收回1000，歉收48%收回650。净利润只统计已收获轮次；种植中投入不提前算成亏损。暂停及离线期间均不推进生长。</p><div class="farm-city-list">${S.cities.filter(farmEligible).map(c=>`<button class="farm-city" onclick="showFarm(${c.id})"><b>${escapeHTML(c.name)}</b><span>${c.dormant?'待接通':farmStageName(c)}</span><small>${c.farm?.crop?farmDate(c.farm.crop.due)+'收获':'每轮 ¥800'}</small></button>`).join('')||'<p>暂时没有中级及以上居住城市。</p>'}</div><h3>最近收获记录</h3>${farmHistory(a.history.slice(-30).reverse())}</div>`);}
const operationsBeforeFarms=showOperations;showOperations=function(){operationsBeforeFarms();$('modal-content').innerHTML+=agricultureSummary();};
const financeBeforeFarms=showFinance;showFinance=function(){financeBeforeFarms();$('modal-content').innerHTML+=agricultureSummary();};
const detailsBeforeFarms=showDetails;showDetails=function(rebuild=true){detailsBeforeFarms(rebuild);let c=(selected?.type==='city'||selected?.type==='stop')&&S.cities[selected.id];if(farmEligible(c)&&!$('details').innerHTML.includes('showFarm('))$('details').innerHTML+=`<section class="city-mission"><b>居民农田</b><p>${c.dormant?'接通城市后可开始种植':farmStageName(c)}</p><button onclick="showFarm(${c.id})">${c.farm?'查看农田与盈亏':'种植农田 · ¥800 / 轮'}</button></section>`;};
const tickBeforeFarms=tick;tick=function(dt){let a=agricultureState();if(a.pending){S.paused=true;maybeFarmHarvest();return;}let wasRunning=!S.paused,next=Math.min(Infinity,...S.cities.map(c=>c.farm?.crop?.due??Infinity)),step=Math.min(dt,Math.max(0,(next-S.day)*12));if(step>0)tickBeforeFarms(step);settleFarms(wasRunning);maybeFarmHarvest();};
const renderBeforeFarms=render;render=function(){maybeFarmHarvest();return renderBeforeFarms();};
const freshBeforeFarms=fresh;fresh=function(){let x=freshBeforeFarms();x.agriculture=null;return x;};
const resetBeforeFarms=reset;reset=function(){farmReviewVisible=false;farmPointer=null;resetBeforeFarms();};
const loadBeforeFarms=load;load=function(){farmReviewVisible=false;farmPointer=null;let ok=loadBeforeFarms();if(ok)settleFarms(false);return ok;};
function farmPosition(c){let signature=S.cities.map(d=>[d.id,d.x,d.y,!!d.removed].join(',')).join(';');if(signature!==farmPlacementKey){farmPlacementKey=signature;farmPlacements.clear();}if(farmPlacements.has(c.id))return farmPlacements.get(c.id);let candidates=[[-66,-12],[66,-45],[-62,-62],[-60,58],[62,60]];for(let [dx,dy] of candidates){let x=c.x+dx,y=c.y+dy;let corners=[{x:x-24,y:y-17},{x:x+24,y:y-17},{x:x+24,y:y+17},{x:x-24,y:y+17}];if(corners.every(p=>p.x<coast(p.y)-8&&(typeof activeAtlasMap!=='undefined'&&activeAtlasMap?riverDistance(p)>27:Math.abs(p.x-river(p.y))>27)&&mountainDistance(p)>4)&&!S.cities.some(d=>d.id!==c.id&&!d.removed&&Math.hypot(d.x-x,d.y-y)<60)){let p={x,y};farmPlacements.set(c.id,p);return p;}}farmPlacements.set(c.id,null);return null;}
function drawFarm(c){if(!c.farm)return;let p=farmPosition(c);if(!p)return;let stage=farmStage(c),recent=!c.farm.crop&&c.farm.lastHarvest&&S.day-c.farm.lastHarvest.day<.15,result=recent?c.farm.lastHarvest.profit>0?1:0:null;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(-.12);ctx.fillStyle='#7c6548';ctx.fillRect(-25,-15,50,33);ctx.fillStyle='#ac8960';ctx.fillRect(-25,-18,50,32);ctx.strokeStyle='#dec69b';ctx.lineWidth=1.4;ctx.strokeRect(-25,-18,50,32);for(let row=0;row<4;row++){ctx.strokeStyle='#816747';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-21,-13+row*7);ctx.lineTo(21,-13+row*7);ctx.stroke();for(let col=0;col<7;col++){if(stage<1&&!recent)continue;if(result===0&&(row+col)%3===0)continue;let x=-19+col*6,y=-12+row*7,h=stage===1?3:stage===2?6:8;ctx.strokeStyle=recent?(result?'#dfb956':'#b49c65'):stage===1?'#7cab65':stage===2?'#8fa951':'#d8b34f';ctx.lineWidth=1.7;ctx.beginPath();ctx.moveTo(x,y+1);ctx.lineTo(x,y-h);ctx.moveTo(x,y-h*.35);ctx.lineTo(x-2.2,y-h*.7);ctx.moveTo(x,y-h*.55);ctx.lineTo(x+2.2,y-h*.88);ctx.stroke();}}if(recent){ctx.strokeStyle=c.farm.lastHarvest.profit>0?'#d8b85f':'#ad8f69';ctx.lineWidth=2;ctx.strokeRect(-29,-22,58,40);}ctx.restore();}
const drawCityBeforeFarms=drawCityArt;drawCityArt=function(c){drawFarm(c);return drawCityBeforeFarms(c);};
// Tap farmland to open its sheet; route dragging and two-finger map gestures keep priority.
cv.addEventListener('pointerdown',e=>{farmPointer=null;if(modalOpen||draft||bridgeDraft||pointers.size>1)return;let p=toWorld(e);if(hitCity(p)||routeHit(p))return;for(let c of S.cities.filter(c=>farmEligible(c)&&c.farm)){let q=farmPosition(c);if(q&&Math.abs(p.x-q.x)<25+8/view.scale&&Math.abs(p.y-q.y)<20+8/view.scale){farmPointer={id:c.id,x:e.clientX,y:e.clientY};break;}}});
cv.addEventListener('click',e=>{let p=farmPointer;farmPointer=null;if(!p||modalOpen||draft||bridgeDraft||pointers.size||Math.hypot(e.clientX-p.x,e.clientY-p.y)>8)return;showFarm(p.id);});
const helpBeforeFarms=help;help=function(){helpBeforeFarms();$('modal-content').innerHTML+='<section class="infra-card"><h3>居民农田</h3><p>点击居住城市查看农田，或从运营中心进入农业经营。每轮投入800，第10天12:00收获：52%收回1000，48%收回650。多块农田合并通知并暂停主世界；收获后手动续种。地图只用翻土、幼苗和成熟作物表示生长。</p></section>';};
// A previously loaded save may be between settlement and acknowledgement.
agricultureState();settleFarms(false);
